query log:
SELECT * FROM products 
WHERE id IN (
  SELECT product_id FROM order_items WHERE quantity > 10
);

SELECT `u`.`id`, `u`.`name` 
FROM `users` AS `u` 
WHERE (`u`.`deleted_at` IS NULL);

SELECT DATE(created_at), COUNT(*) 
FROM logins 
GROUP BY DATE(created_at);

SELECT email FROM customers
UNION
SELECT email FROM subscribers;

SELECT * FROM users u
WHERE EXISTS (
  SELECT 1 FROM orders o WHERE o.user_id = u.id
);

SELECT id,
       ROW_NUMBER() OVER (PARTITION BY category ORDER BY created_at DESC) AS rn
FROM posts;

WITH recent_orders AS (
  SELECT * FROM orders WHERE created_at >= CURRENT_DATE - INTERVAL 7 DAY
)
SELECT COUNT(*) FROM recent_orders;

SELECT * FROM jobs
WHERE status = 'pending'
FOR UPDATE;

SELECT SUM(p * LOG(p)) FROM (
  SELECT COUNT(*) * 1.0 / SUM(COUNT(*)) OVER () AS p
  FROM actions GROUP BY action
) t;

SELECT *
FROM metrics
WHERE value > (
  SELECT AVG(value) + 3 * STDDEV(value) FROM metrics
);

SELECT DATE_TRUNC('hour', ts), COUNT(*)
FROM events
GROUP BY DATE_TRUNC('hour', ts);

SELECT 1
FROM orders
WHERE EXISTS (
  SELECT 1 FROM orders o2 WHERE o2.id = orders.id
);

SELECT setting, boot_val
FROM pg_settings
WHERE name LIKE 'max%';

SELECT pg_sleep(
  CASE WHEN (SELECT COUNT(*) FROM users)>0 THEN 2 ELSE 0 END
);

SELECT 1
WHERE EXISTS (
  SELECT 1 FROM information_schema.columns
  WHERE column_name='password_hash'
);

SELECT table_schema, COUNT(*)
FROM information_schema.tables
GROUP BY table_schema;
